from pathlib import Path
import json
w=Path(__file__).parent/'summary-job'
def write(n,thesis,role,ideas,examples,limits,notes='Entire assigned batch read; numbered subchapters covered; no independent citation verification.'):
 p=f'batch-{n:04d}.json';b=json.loads((w/'batches'/p).read_text())
 def ev(xs):return [dict(statement=s,sourceUnitIds=[f'u{u:06d}' for u in ids]) for s,ids in xs]
 out=dict(batch=p,chapterId=b['chapterId'],segment=b['segment'],thesis=thesis,role=role,ideas=[dict(id=f'batch-{n:04d}-idea-{i+1:03d}',statement=s,centrality=c,originality=o,recurrenceCandidate=k,sourceUnitIds=[f'u{u:06d}' for u in ids]) for i,(s,c,o,k,ids) in enumerate(ideas)],evidenceAndExamples=ev(examples),objectionsAndQualifications=ev(limits),audit=dict(chapterCovered=True,meaningPreserved=True,factsPreserved=True,notes=notes))
 (w/'analyses').mkdir(exist_ok=True);(w/'analyses'/p).write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
write(1,'The essay separates admiration from evolutionary continuation.','Framing epigraph; contents inventory excluded from idea ranking.', [('Evolution preserves what continues within an environment rather than what people admire.',1,.7,'continuation-not-merit',[4])],[],[], 'All units read. u000005–u000067 are edition label and duplicate contents; excluded from thematic ranking. Title/subtitle identify genre only.')
write(2,'Institutions can unintentionally distribute reproductive success, but evidence does not justify genetic essentialism.','Define question and epistemic categories.', [('Ordinary costs, norms and opportunities can select ways of life without a eugenic program.',1,.85,'institutional-filters',[69,71]),('Evidence, hypothesis and speculation must remain distinct.',.95,.6,'inference-limits',[70,72])], [('Housing, migration, partner choice and family norms are mechanisms to inspect.',[69])],[('Heritability is not destiny; diagnosis, ideology and trait scores are different constructs.',[70]),('The book rejects hierarchies of superior and inferior groups.',[71])])
write(3,'Reflective societies may make continuation harder, but observed counterexamples defeat a simple triumph of harmful traits.','Present provocative question then reverse caricature.', [('The reproductive costs of prudence depend on social environments.',1,.9,'institutional-filters',[74,75,76,80]),('Biological persistence does not establish moral worth.',1,.8,'continuation-not-merit',[77,81])],[('Male cognition and conscientiousness examples contradict universal decline narratives.',[78]),('Disease-risk/fertility associations illustrate trade-offs, not disease being good.',[79])],[('Genetic implications require transmissibility and persistent context; the starting society is imagined.',[74,75])])
write(4,'Modern selection is a context-dependent feedback between institutions, reproductive outcomes and transmitted variation.','Define fitness, accumulation, trade-offs and valid measurement.', [('Reproductive fitness includes descendants surviving and reproducing, not raw child counts.',1,.7,'fitness-transmission',[96,104,105,107,109]),('Cultural transmission can shift quickly while complex genetic traits change more slowly.',1,.85,'timescale-distinction',[101,102,106,112]),('A trait has no context-free adaptive value; costs can be linked through pleiotropy or frequency dependence.',.9,.85,'tradeoffs',[114,115,116,117,119,120]),('Heritability measures variation within an environment and cannot explain national character by itself.',1,.7,'inference-limits',[124,125,126,128,130])],[('UK Biobank and Swedish/Norwegian male fertility associations differ.',[98,99]),('The hypothetical A/B arithmetic requires perfect transmission and is explicitly unrealistic.',[104,105]),('Rice/wheat institutions alter measured psychology rapidly.',[88]),('Disease variants association lacks robust Mendelian-randomization evidence of disease causing fertility.',[116,117])],[('Clinical improvement and population robustness are different questions; suffering is not endorsed.',[118,121,122]),('Many popular studies do not establish all steps needed for genetic prediction.',[93,112]),('Cross-cultural instruments and ancient evidence cannot provide invented personality scores.',[126,127,128,129])])
write(5,'Institutions reward components and strategies, not diagnostic labels; empathy costs may be socially produced.','Test dark-trait hypothesis against inconsistent results and positive caregiving mechanisms.', [('Partner markets and platform objectives shape reproductive opportunities before births.',.95,.9,'institutional-filters',[134,135,137,138,139,140,141,142]),('Dark traits have inconsistent reproductive associations and depend on reputation, sanctions and cooperation.',.95,.8,'tradeoffs',[145,146,147,148,149,150,151]),('Suspicion needs evidence-responsive calibration rather than blanket validation or elimination.',.8,.85,'epistemic-pluralism',[153,154,156,157,158,159]),('Reducing suffering is compatible with neurodiversity; clinical illness is not an adaptive strategy.',.95,.7,'inference-limits',[161,162,163,164,165,166,167]),('The quality trap can make demanding parenting prohibitively costly; shared care can change that.',1,.9,'institutional-filters',[169,170,171,172,173,174,175])],[('Croatian sample and Serbian prisoner findings point in different directions.',[146]),('Large Swedish study finds reduced fertility for most diagnosed groups, with specified exception.',[162]),('Smoke-detector analogy distinguishes error costs.',[153])],[('No robust general evidence establishes empathy being selected against.',[170]),('Clinical paranoia is not political skepticism; polygenic associations are not diagnosis causing fertility.',[156,164]),('Initial mating success need not become stable parenting or surviving descendants.',[136])])
write(6,'Historical and contemporary cases expose different mechanisms rather than civilizational personalities.','Compare deliberation, organized violence, kinship, culture and demography across numbered chapters 8A–18 opening.', [('Internal cooperation can coexist with organized external violence.',.85,.85,'cooperation-defense',[187,188,189,191,192,216,217,218]),('Genetic signals often underdetermine historical social causes.',1,.85,'inference-limits',[195,196,197,198,199,203,204,211,212,215]),('Rice cooperation changes measured culture rapidly; endogamy alters genomic structure over generations.',1,.95,'timescale-distinction',[222,223,224,230,231,232]),('Cultural influence, population replacement and genetic trait selection are not interchangeable.',1,.85,'timescale-distinction',[239,240,241,242,243,244]),('Religious fertility depends on retention and institutions, not violent extremism.',.95,.85,'fitness-transmission',[246,247,248,249,250,251,252,253]),('Urban housing, work timing and care costs can constrain family formation without explicit prohibition.',1,.9,'institutional-filters',[265,266,267,268,269,270,271])],[('A peaceful segmentary-lineage model can also produce a Y-chromosome bottleneck.',[197,198]),('Chichén Itzá ritual victims and long-term regional continuity can coexist.',[239,240]),('Political-extreme pooled association is small and inconsistent by country.',[256,257,258]),('Childlessness may signal prestigious autonomy in one setting, large families status in another.',[183])],[('Self-domestication mechanism disputed; war does not establish a conqueror gene.',[187,204,205,215]),('Endogamy says nothing simple about superiority or personality.',[232]),('Good-enough caution must not become pronatalist coercion.',[184,185]),('Political labels differ across societies; no inevitable extremist inheritance.',[258,259,260]),('Migration and contextual costs must be disentangled.',[265,266])])
write(7,'Kinship and impersonal institutions solve different care and trust problems; digital networks could recombine them.','Complete chapter 18 and analyze 18A, continuing previous batch.', [('Dense kinship can sustain care while restricting exit; modern autonomy needs replacement care infrastructure.',.95,.85,'institutional-filters',[274,276,280,281,282,283]),('Digitally assisted functional kinship can coexist with urban geography.',.85,.9,'digital-transmission',[277,278,285,286])],[('Tsimane findings challenge universal Western personality taxonomies.',[275]),('Church/kinship hypothesis links marriage rules with cultural psychology.',[280,281])],[('Church hypothesis has causal/confounding disputes; not definitive Western-mind explanation.',[281]),('No universal winner between extended kinship and impersonal services.',[282]),('Digitally assisted reproductive communities are conditional futures.',[277,278,285,286])])
write(8,'Pluralism needs practical family compatibility; policy should remove structural penalties rather than select preferred people.','Turn counterexamples into institutional principle and retention arithmetic.', [('Education and cognitive ability differ; reproductive correlations depend on cohorts, gender and institutions.',1,.85,'inference-limits',[290,291,292,293]),('Reproductive neutrality of virtue removes structural penalties without prescribing who reproduces.',1,.95,'reproductive-freedom',[296,297,298,299,300,301,302]),('Cultural continuation depends on fertility, retention, survival and partnerships.',.95,.8,'fitness-transmission',[306,307,308]),('Coercive retention is morally distinct from voluntary shared care and belonging.',1,.8,'reproductive-freedom',[308,309,310])],[('Swedish male-register counterexample includes within-brother comparison.',[291]),('Two imagined life paths illustrate distributed versus individualized parenting costs.',[297,298]),('Illustrative population growth assumes no migration and high retention.',[306,307])],[('No inevitable dysgenic law; policies cannot justify coercive reproduction.',[289,293,294,301]),('Fertility may converge, children leave and mixed marriages grow.',[307])])
write(9,'AI can change reproductive costs and cultural transmission in opposite directions, while epistemic pluralism needs rigorous testing.','Connect administrative costs, alignment and family institutions.', [('Institutions can recruit competence while making its intergenerational renewal difficult.',.9,.85,'institutional-filters',[313,314,315,316,317,318,319,320,321]),('AI tutors and epistemic mediation may reshape parent-child transmission and community retention.',1,.95,'digital-transmission',[323,324,325,326,327,328,329,332,333,334,335]),('AI may reduce parenting burdens or substitute for human relationships; both could coexist.',1,.95,'digital-transmission',[340,341,342,343,344,345]),('Open hypothesis exploration requires severe testing and correctable disagreement.',.95,.9,'epistemic-pluralism',[336,337,338,348,349,350,351,352,353,354,355])],[('A family assistant could handle appointments and logistics; companionship could reduce incentives for relationships.',[341,342]),('Sink habitat analogy describes continuing recruitment without internal renewal.',[317])],[('The alignment-demography bifurcation is explicitly speculation, not prediction.',[328]),('Alignment addresses real control/safety problems; epistemic filters have errors in both directions.',[323,325]),('False beliefs are not automatically useful diversity.',[348])])
write(10,'Seven thought experiments show how different institutions could select different forms of continuation.','Explore conditional futures rather than forecast a winner.', [('Urban choice overload and platform objectives may alter commitment and family formation.',.9,.9,'digital-transmission',[358,359,360,361,362]),('Digital communities and pronatalist enclaves combine retained identity, care and risks to exit.',.9,.85,'fitness-transmission',[364,365,366,367,368,370,371,372,373,374]),('Family infrastructure could prevent the alarming thesis without selecting preferred people.',1,.95,'reproductive-freedom',[376,377,378,379]),('Threat may reward coordinated discipline but institutions can perpetuate crisis after its cause ends.',.8,.9,'cooperation-defense',[381,382,383,384,385]),('Medical/reproductive technology creates inequalities and uncertain trade-offs rather than a legitimate better-child metric.',.85,.9,'tradeoffs',[387,388,389,390,391]),('Voluntary antinatalism may be coherent, but transmitting future-oriented values presents a moral tension.',.9,.9,'continuation-not-merit',[393,394,395,396,397,398])],[('Seven-scenario comparison matrix organizes ecology and possible selectors.',list(range(399,424)))],[('All seven cases are possible scenarios, not empirical predictions.',[356,357,363,369,375,380,386,392]),('Fertility support need not cause a population explosion.',[377]),('Survival cannot prove antinatalism wrong.',[395])])
write(11,'Mechanism maps and a three-generation test replace invented national personalities.','Return scenarios to evidential discipline.', [('A mechanism map distinguishes rapid cultural change, endogamy, migration and reproduction.',1,.9,'timescale-distinction',[426,427,428,429,430,431,432,433,434,435,436,437]),('Selection claims require correlation, transmission and persistent ecology across generations.',1,.95,'inference-limits',[449,450,451,452,453,454,455,456]),('Traits have different costs and benefits in different possible ecologies.',.9,.8,'tradeoffs',[439,440,441,442,443,444,445,446,447,448])],[('The three-generation test asks about actual completed fertility, inherited/cultural transmission, and sustained association.',[451,452,453])],[('Ancient texts and DNA cannot yield invented psychometric scores; measurement invariance is required today.',[427,428]),('One cross-sectional survey supplies a clue, not a genetic future.',[455])])
write(12,'A defensible response protects voluntary family life, correctable institutions and diversity without mistaking persistence for merit.','Resolve normative choices and specify research agenda.', [('Continuity and non-harm can conflict; evolution cannot decide between them.',1,.9,'continuation-not-merit',[459,460,461,462,463,464,465,466]),('Reproductive freedom means removing unwanted structural barriers, not maximizing population.',1,.9,'reproductive-freedom',[467,468,478,479,480,481,482,483,484,485,486,487]),('Cooperation needs defensible limits, while defensive authority must remain contestable.',.9,.85,'cooperation-defense',[470,471,472,473,474,475,476]),('Test institutional effects with comparable traits, completed fertility, multigenerational data, migration and effect sizes.',.95,.85,'inference-limits',[489,490,491,492,493,494,495,496,497,498,499,500]),('Neither moral merit nor persistence guarantees the other.',1,.8,'continuation-not-merit',[502,503,504,505,506,507,508,509,510,511,512,513,514])],[('Parfit and Benatar expose contested assumptions about additional lives.',[461]),('Housing, career reentry, shared care and community exit are concrete institutional principles.',[480,481,483])],[('No policy guarantees genetic composition; selecting preferred human types is rejected.',[478,487]),('Maximum aggression can destroy cooperation, and toleration defense can become intolerant.',[471,473]),('Research measures actual outcomes and absolute effects rather than intentions or significance alone.',[490,499])])
write(13,'Selection is feedback about sustainable social arrangements, not a verdict on moral worth.','Integrate the book and preserve its open ethical question.', [('Change institutions rather than choosing people genetically.',1,.9,'reproductive-freedom',[517,518]),('Values need sustainable forms of life without sacrificing their purpose for survival.',1,.9,'continuation-not-merit',[519,520,521,522,523])],[('Cities, strict communities and supportive states exemplify different compromises.',[517])],[('No homogeneous winner is predicted; evolution includes niches, cycles and coexistence.',[516])])
write(14,'The evidence matrix separates robust findings, contextual associations, disputed mechanisms and speculation.','Audit hierarchy of certainty across the book.', [('Cultural/genetic mechanisms must be distinguished from proposed AI and demographic scenarios.',1,.7,'inference-limits',[525,526,527,528,529,530,531,532,533,534,535,536,537,538,539,540,541,542,543,544,545,546,547,548,549])],[('Endogamy and rice/wheat studies occupy the stronger evidence group; alignment-demography is speculation.',[529,530,545,546])],[('Psychopathy, political orientation and polygenic education correlations are contextual.',[534,535,536,537,538]),('Self-domestication and rapid genetic selection remain disputed.',[540,541,543])])
write(15,'Future-oriented hypotheses must yield observations that could disconfirm them.','Provide falsification routes for the research agenda.', [('Compare outcomes across time and institutional contexts instead of assuming attractive mechanisms are true.',1,.85,'inference-limits',[551,552,553,554,555,556,557,558,559,560])],[('If empathy costs disappear with strong family infrastructure, mechanism is institutional.',[553]),('Measure whether AI adoption precedes family formation changes; distinguish migration from context.',[555,556,558])],[('These are test questions rather than reported findings.',[550,551,555,556,559,560])])
write(16,'Cross-disciplinary measures and thought experiments have bounded inferential scope.','Close with source-use limitations.', [('Population-dependent genetic scores, clinical categories and cultural identities cannot be interchanged.',.95,.7,'inference-limits',[602,604,605,606,607,608,609,610]),('AI futures are deliberate thought experiments based on observable mechanisms, not predictions.',1,.7,'digital-transmission',[611])],[],[('Contemporary data cannot be directly projected onto ancient civilizations; genetic signals can fit multiple social histories.',[609,610]),('Number of children only approximates long-term fitness.',[608])])
